package com.mci.agents;

import com.mci.core.*;
import com.mci.gateway.ToolGateway;
import dev.langchain4j.model.chat.ChatLanguageModel;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Map;

/**
 * Dedicated agent for synthesizing multi-agent findings and producing the executive
 * Markdown report (report.md).
 *
 * Saves report.md in the workspace run folder strictly through the ToolGateway.
 * (Results in PDF format are generated by DataFileAgent).
 */
public class ReportAgent implements Agent {

    private static final Logger log = LoggerFactory.getLogger(ReportAgent.class);

    private final ChatLanguageModel model;
    private final ToolGateway gateway;

    public ReportAgent(ChatLanguageModel model, ToolGateway gateway) {
        this.model = model;
        this.gateway = gateway;
    }

    @Override
    public AgentResult execute(SubTask subTask) {
        log.info("ReportAgent compiling executive report for: {}", subTask.description());

        try {
            String prompt = """
                    You are a specialized REPORT agent in a multi-agent system.
                    Your subtask is: %s

                    Synthesize all research findings and intelligence into a high-level Executive Markdown Report.
                    Ensure the report is clearly structured with distinct sections, paragraphs, bullet points, and key metrics.

                    Produce the report in this structure:
                    # Executive Intelligence Report: <Subject>

                    ## 1. Executive Summary
                    <High-level overview of the objective, scope, and primary strategic outcomes>

                    ## 2. Research Findings & Key Highlights
                    - <Key finding 1 with analysis>
                    - <Key finding 2 with analysis>
                    - <Key finding 3 with analysis>

                    ## 3. Quantitative Insights & Benchmark Data
                    - <Metric 1>: <Value and context>
                    - <Metric 2>: <Value and context>

                    ## 4. Multi-Agent System Security & Governance
                    <Verification of tool permissions, sandbox isolation, and policy enforcement>

                    ## 5. Strategic Recommendations & Next Steps
                    <Concluding recommendations for leadership>
                    """
                    .formatted(subTask.description());

            String reportContent = LlmFactory.generateWithRetry(model, prompt);

            // Write Markdown report via ToolGateway (report.md only)
            String reportPath = subTask.runId() + "/report.md";
            ToolRequest writeRequest = new ToolRequest(
                    subTask.runId(),
                    subTask.id(),
                    AgentType.REPORT,
                    "file.write",
                    Map.of("path", reportPath, "content", reportContent)
            );
            ToolResponse writeResponse = gateway.execute(writeRequest);

            if (writeResponse.success()) {
                return AgentResult.success("Executive Markdown report compiled successfully.\n[Report Saved: " + reportPath + "]");
            } else {
                return AgentResult.failure("Gateway rejected report write: " + writeResponse.error());
            }

        } catch (Exception e) {
            log.error("ReportAgent failed: {}", e.getMessage(), e);
            return AgentResult.failure("ReportAgent error: " + e.getMessage());
        }
    }
}
